// Plan karşılaştırmasının saf fiyat mantığı: yıllık indirim hesabı ve tutar yazımı. React ve CSS içermez; test doğrudan bunu okur.
import { math, money } from "@snn/abacus-core";

export type PlanId = "team" | "studio";
export type BillingPeriod = "monthly" | "yearly";

/** Aylık liste fiyatı (TRY, kullanıcı başına) ve yıllık planda uygulanan indirim yüzdesi. */
export const MONTHLY_PRICE: Record<PlanId, number> = { team: 399, studio: 849 };
export const YEARLY_DISCOUNT_PERCENT: Record<PlanId, number> = { team: 20, studio: 20 };

/** Yıllık planda ayın eşdeğer fiyatı: aylık fiyattan yüzde indirim düşülür, tam liraya yuvarlanır. */
export function yearlyEquivalent(monthly: number, discountPercent: number): number {
  const rate = math.div(discountPercent, 100) ?? 0;
  return math.round(math.mul(monthly, math.sub(1, rate)), 0);
}

/** Plan ve dönem için kullanıcı başına aylık tutar (TRY). */
export function planPrice(plan: PlanId, period: BillingPeriod): number {
  const monthly = MONTHLY_PRICE[plan];
  return period === "yearly" ? yearlyEquivalent(monthly, YEARLY_DISCOUNT_PERCENT[plan]) : monthly;
}

/** Aylık fiyata göre indirim yüzdesi, tam sayıya yuvarlanır. Aylık fiyat sıfır ya da geçersizse 0. */
export function savingsPercent(monthly: number, yearly: number): number {
  if (!Number.isFinite(monthly) || !Number.isFinite(yearly)) return 0;
  const percent = math.percent(math.sub(monthly, yearly), monthly);
  return percent === null ? 0 : math.round(percent, 0);
}

/** Planlar arasındaki en yüksek yıllık indirim yüzdesi ("en çok %20 indirim" yazısı için). */
export function maxSavingsPercent(): number {
  const percents = (Object.keys(MONTHLY_PRICE) as PlanId[]).map(plan => savingsPercent(MONTHLY_PRICE[plan], planPrice(plan, "yearly")));
  return math.max(...percents) ?? 0;
}

/** Para birimi simgesi ("TRY" → "₺"); ABACUS simgeyi tutarın önüne koyar, simge sıfır tutarın yazımından ayıklanır. */
export function currencyPrefix(currency = "TRY"): string {
  const zero = money.formatMajor(0, { currency, digits: 0, zero: "symbol" });
  return zero === "—" ? "" : zero.replace(/0$/, "");
}

/** Tam sayı tutarın binlik ayraçlı yazımı: 1249 → "1.249". */
export function formatAmount(amount: number): string {
  return money.fmtDecimalGrouped(amount, 0);
}

.comparison { box-sizing: border-box; width: min(100%, 1060px); min-width: 0; margin-inline: auto; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: var(--tracking-body); line-height: var(--leading-body); }
.comparison *, .comparison *::before, .comparison *::after { box-sizing: border-box; }

/* Giriş */
.intro { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px 32px; padding: 32px 32px 24px; }
.intro > div:first-child { min-width: 0; max-width: 560px; }
.intro h2 { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 400; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.intro p { max-width: 46ch; margin: 8px 0 0; color: var(--text-secondary); text-wrap: pretty; }
.billing { display: grid; flex: none; justify-items: end; gap: 6px; }
.billing small { min-height: 16px; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }

/* Süzgeç çubuğu */
.filter { display: flex; min-height: 52px; align-items: center; justify-content: space-between; gap: 8px 16px; border-top: 1px solid var(--border); padding: 8px 32px; }
.filter > div:first-child { display: flex; align-items: baseline; gap: 10px; }
.filter h3 { margin: 0; font-size: var(--text-sm); font-weight: 500; }
.featureCount { min-width: 11ch; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.filter > button { flex: none; }

/* Karşılaştırma tablosu */
.matrix { border-top: 1px solid var(--border); }
.planHeader, .featureRow { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr) minmax(0, 1fr); }
/* Plan hücreleri üç satır izini paylaşır (ad, fiyat, düğme); bir sütunda açıklama alt satıra sarsa bile fiyatlar ve düğmeler aynı hizada kalır. */
.planHeader { grid-template-rows: auto auto auto; }
.featureHeader { grid-row: 1 / span 3; display: flex; align-items: end; padding: 0 16px 20px 32px; color: var(--text-muted); font-size: var(--text-xs); }
.planCell { position: relative; display: grid; grid-row: span 3; grid-template-rows: subgrid; min-width: 0; align-content: start; border-left: 1px solid var(--border); padding: 20px; transition: background-color var(--duration-standard) var(--ease-standard); }
.planCell.planSelected, .featureValue.valueSelected { background: var(--surface-muted); }
.planTop h3 { margin: 0; font-size: var(--text-base); font-weight: 500; letter-spacing: -.01em; }
.planTop > span { display: block; margin-top: 2px; color: var(--text-muted); font-size: var(--text-xs); }
.price { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 6px; margin: 16px 0 14px; }
.priceValue { display: inline-flex; min-width: 3ch; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 400; letter-spacing: var(--tracking-display); line-height: 1; font-variant-numeric: tabular-nums; }
.pricePeriod { color: var(--text-muted); font-size: var(--text-xs); white-space: nowrap; }
.selectButton { width: 100%; }
.selectedRail { position: absolute; right: 0; bottom: -1px; left: 0; height: 2px; background: var(--accent); }
.rows { border-top: 1px solid var(--border); }
.featureRow { overflow: hidden; border-bottom: 1px solid var(--border-subtle); }
.featureRow:last-child { border-bottom: 0; }
.featureName, .featureValue { display: flex; min-width: 0; min-height: 44px; align-items: center; padding: 10px 20px; }
.featureName { padding-left: 32px; color: var(--foreground); }
.featureValue { border-left: 1px solid var(--border); color: var(--text-secondary); transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard); }
.featureValue.valueSelected { color: var(--foreground); }
.included { display: inline-flex; align-items: center; gap: 6px; color: var(--foreground); }
.included svg { color: var(--success); }
.unavailable { color: var(--text-muted); }
.mobilePlan { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.footer { display: flex; min-height: 48px; align-items: center; justify-content: space-between; gap: 8px 24px; border-top: 1px solid var(--border); padding: 12px 32px; color: var(--text-muted); font-size: var(--text-xs); }
.footer p { min-height: 1.4em; margin: 0; color: var(--text-secondary); text-align: right; }

@media (hover: hover) and (pointer: fine) {
  .featureRow:hover .featureName { color: var(--foreground); }
}

/* Yerleşim görüntü alanını değil, blok genişliğini izler (data-size, bileşende ölçülür). */
/* Orta: üç sütun kalır, boşluklar daralır. */
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .intro { flex-direction: column; align-items: flex-start; padding: 24px 20px 20px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .billing { justify-items: start; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .filter { padding-inline: 20px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .featureHeader, .comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .featureName { padding-left: 20px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .planCell { padding: 16px 14px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .featureValue { padding-inline: 14px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .footer { flex-direction: column; align-items: flex-start; padding-inline: 20px; }
.comparison:is([data-size="md"], [data-size="sm"], [data-size="xs"]) .footer p { text-align: left; }

/* Dar: özellik adı iki değerinin üstünde durur; değerler plan sütunlarının altında hizalı kalır. */
.comparison:is([data-size="sm"], [data-size="xs"]) .intro h2 { font-size: var(--text-2xl); }
.comparison:is([data-size="sm"], [data-size="xs"]) .filter { flex-wrap: wrap; }
.comparison:is([data-size="sm"], [data-size="xs"]) .planHeader, .comparison:is([data-size="sm"], [data-size="xs"]) .featureRow { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.comparison:is([data-size="sm"], [data-size="xs"]) .featureHeader { display: none; }
.comparison:is([data-size="sm"], [data-size="xs"]) .planCell { border-left: 0; }
.comparison:is([data-size="sm"], [data-size="xs"]) .planCell + .planCell { border-left: 1px solid var(--border); }
.comparison:is([data-size="sm"], [data-size="xs"]) .priceValue { font-size: var(--text-2xl); }
.comparison:is([data-size="sm"], [data-size="xs"]) .featureName { grid-column: 1 / -1; min-height: 0; padding: 10px 20px 0; color: var(--text-secondary); font-size: var(--text-xs); }
.comparison:is([data-size="sm"], [data-size="xs"]) .featureValue { min-height: 0; border-left: 0; padding: 4px 14px 10px; }
.comparison:is([data-size="sm"], [data-size="xs"]) .featureValue:nth-child(2) { padding-left: 20px; }
.comparison:is([data-size="sm"], [data-size="xs"]) .featureValue + .featureValue { border-left: 1px solid var(--border-subtle); }
.comparison:is([data-size="sm"], [data-size="xs"]) .planCell:nth-child(2) { padding-left: 20px; }
.comparison[data-size="xs"] .planCell { padding-inline: 12px; }
.comparison[data-size="xs"] .planCell:nth-child(2) { padding-left: 16px; }
.comparison[data-size="xs"] .featureValue { padding-inline: 12px; }
.comparison[data-size="xs"] .featureValue:nth-child(2) { padding-left: 16px; }
.comparison[data-size="xs"] .featureName { padding-inline: 16px; }
.comparison[data-size="xs"] .intro, .comparison[data-size="xs"] .filter, .comparison[data-size="xs"] .footer { padding-inline: 16px; }
@media (prefers-reduced-motion: reduce) {
  .planCell, .featureValue { transition: none; }
}

.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { animate, AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Check } from "lucide-react";
import { Button } from "../button/button";
import SegmentedControl from "../segmented-control/segmented-control";
import { Switch } from "../switch/switch";
import { motionTokens } from "../lib/motion-tokens";
import { currencyPrefix, formatAmount, maxSavingsPercent, planPrice, type BillingPeriod, type PlanId } from "./plan-comparison-format";
import styles from "./plan-comparison.module.css";

/** Plan görünen adları ve kısa tanımları. */
const PLAN_NAMES: Record<PlanId, string> = { team: "Takım", studio: "Stüdyo" };
const PLAN_TAGLINES: Record<PlanId, string> = { team: "Küçük ekipler için", studio: "Birden çok ekibin işi için" };

const INCLUDED = "Dahil";
const NOT_INCLUDED = "Dahil değil";
type Feature = { label: string; team: string; studio: string; shared?: boolean };

const features: Feature[] = [
  { label: "Etkin projeler", team: "Sınırsız", studio: "Sınırsız", shared: true },
  { label: "Ortak çalışma alanları", team: "1 alan", studio: "Sınırsız" },
  { label: "Konuk inceleyiciler", team: "Projede 5", studio: "Sınırsız" },
  { label: "Sürüm geçmişi", team: "30 gün", studio: "Sınırsız" },
  { label: "Onay akışları", team: NOT_INCLUDED, studio: INCLUDED },
  { label: "Özel roller", team: NOT_INCLUDED, studio: INCLUDED },
  { label: "Kaynak dışa aktarma", team: INCLUDED, studio: INCLUDED, shared: true },
  { label: "Destek", team: "E-posta", studio: "Öncelikli e-posta" },
];

function Value({ text }: { text: string }) {
  if (text === INCLUDED) return <span className={styles.included}><Check size={16} strokeWidth={1.75} aria-hidden="true" />{INCLUDED}</span>;
  return <span className={text === NOT_INCLUDED ? styles.unavailable : undefined}>{text}</span>;
}

/** Sayıya dönen metin. `format` verilirse gösterilen tam sayı onunla yazılır (ör. binlik ayraç). */
function AnimatedNumber({ value, format }: { value: number; format?: (value: number) => string }) {
  const reduce = useReducedMotion();
  const [displayValue, setDisplayValue] = useState(value);
  const previousValue = useRef(value);

  useEffect(() => {
    if (reduce) {
      previousValue.current = value;
      return;
    }

    const controls = animate(previousValue.current, value, {
      duration: motionTokens.duration.standard,
      ease: [...motionTokens.ease.enter],
      onUpdate: (latest) => setDisplayValue(Math.round(latest)),
    });

    previousValue.current = value;
    return () => controls.stop();
  }, [reduce, value]);

  const shown = reduce ? value : displayValue;
  return <>{format ? format(shown) : shown}</>;
}

export function PlanComparison() {
  const id = useId();
  const reduce = useReducedMotion();
  const [billing, setBilling] = useState<BillingPeriod>("monthly");
  const [differencesOnly, setDifferencesOnly] = useState(false);
  const [selected, setSelected] = useState<PlanId | null>(null);
  const rootRef = useRef<HTMLElement>(null);
  const [size, setSize] = useState<"lg" | "md" | "sm" | "xs">("lg");
  useLayoutEffect(() => {
    const node = rootRef.current;
    if (!node) return;
    const measure = (width: number) => setSize(width <= 340 ? "xs" : width <= 540 ? "sm" : width <= 720 ? "md" : "lg");
    measure(node.getBoundingClientRect().width);
    const observer = new ResizeObserver(([entry]) => { if (entry) measure(entry.contentRect.width); });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  const visibleFeatures = differencesOnly ? features.filter((feature) => !feature.shared) : features;

  return (
    <section ref={rootRef} className={styles.comparison} data-size={size} aria-labelledby={`${id}-title`}>
      <div className={styles.intro}>
        <div><h2 id={`${id}-title`}>Çalışma biçiminize yer var</h2><p>Yalnızca planlar arasında değişen ayrıntılar. Ne ödeyeceğinizi görmek için faturalama dönemini değiştirin.</p></div>
        <div className={styles.billing}><SegmentedControl label="Faturalama dönemi" value={billing} onValueChange={(value) => setBilling(value as BillingPeriod)} options={[{ value: "monthly", label: "Aylık" }, { value: "yearly", label: "Yıllık" }]} /><small>{billing === "yearly" ? `Yıllık faturalanır, en çok %${maxSavingsPercent()} indirim` : "Ay ay faturalanır"}</small></div>
      </div>

      <div className={styles.filter}><div><h3>Planları karşılaştır</h3><span className={styles.featureCount}><AnimatedNumber value={visibleFeatures.length} /> / {features.length} özellik</span></div><Switch checked={differencesOnly} onCheckedChange={setDifferencesOnly} label="Yalnızca farkları göster" /></div>

      <div className={styles.matrix} role="table" aria-label="Takım ve Stüdyo planı karşılaştırması">
        <div className={styles.planHeader} role="row">
          <div className={styles.featureHeader} role="columnheader">Ne değişiyor</div>
          {(["team", "studio"] as const).map((plan) => (
            <div key={plan} className={`${styles.planCell} ${selected === plan ? styles.planSelected : ""}`} role="columnheader" aria-label={`${PLAN_NAMES[plan]} planı`}>
              <div className={styles.planTop}><h3>{PLAN_NAMES[plan]}</h3><span>{PLAN_TAGLINES[plan]}</span></div>
              <div className={styles.price}><span className={styles.priceValue} aria-live="polite" aria-atomic="true">{currencyPrefix()}<AnimatedNumber value={planPrice(plan, billing)} format={formatAmount} /></span><span className={styles.pricePeriod}>kullanıcı başına / ay</span></div>
              <Button type="button" variant={selected === plan ? "primary" : "secondary"} className={styles.selectButton} aria-pressed={selected === plan} onClick={() => setSelected(current => current === plan ? null : plan)}>{selected === plan ? "Seçildi" : `${PLAN_NAMES[plan]} planını seç`}</Button>
              {selected === plan && <motion.span className={styles.selectedRail} layoutId={`${id}-selected-rail`} transition={reduce ? { duration: 0 } : motionTokens.spring.responsive} aria-hidden="true" />}
            </div>
          ))}
        </div>

        <div className={styles.rows} role="rowgroup">
          <AnimatePresence initial={false}>
            {visibleFeatures.map((feature) => (
              <motion.div key={feature.label} className={styles.featureRow} role="row" initial={reduce ? false : { height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={reduce ? undefined : { height: 0, opacity: 0, transition: { height: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.fast } } }} transition={reduce ? { duration: 0 } : { height: motionTokens.spring.smooth, opacity: { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter], delay: .04 } }}>
                <div className={styles.featureName} role="rowheader">{feature.label}</div>
                <div className={`${styles.featureValue} ${selected === "team" ? styles.valueSelected : ""}`} role="cell"><span className={styles.mobilePlan}>{PLAN_NAMES.team}</span><Value text={feature.team} /></div>
                <div className={`${styles.featureValue} ${selected === "studio" ? styles.valueSelected : ""}`} role="cell"><span className={styles.mobilePlan}>{PLAN_NAMES.studio}</span><Value text={feature.studio} /></div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      </div>

      <div className={styles.footer}><span>Fiyatlar kullanıcı başına TRY cinsindendir. Yıllık planlar yıllık faturalanır.</span><p className={styles.srOnly} role="status" aria-live="polite">{selected ? `${PLAN_NAMES[selected]} planı seçildi` : ""}</p></div>
    </section>
  );
}

export default PlanComparison;
